actions.script:
const out = ec.service.sync().name('ironstone.projects.CodeServices.get#MergeRequestChanges').parameters({mergeRequestId: mergeRequestId || ''}).call() || {}
if (!ec.message.hasError() && !out.found) ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} is not available', '', {mergeRequestId}))
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {changes: out.changes})

const out = ec.service.sync().name('ironstone.projects.CodeServices.comment#MergeRequest').parameters({mergeRequestId: mergeRequestId || '', body: body || '',
    path: path || null, oldLine: oldLine ? Number(oldLine) : null, newLine: newLine ? Number(newLine) : null, lineText: lineText || null,
    parentCommEventId: parentCommEventId || null}).call() || {}
// a comment on a merge request with a public conversation may be held for review: it is then in no thread yet
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {communicationEventId: out.communicationEventId, held: !!out.held,
    ...(out.held ? {messageInfos: [{type: 'info', message: ec.l10n.localize('Your comment is held for review: it shows here once a moderator approves it')}]} : {})})

// the thread must be of this merge request
const anchor = communicationEventId ? ec.service.sync().name('mantle.work.GitServices.get#ReviewThreads').parameters({mergeRequestId: mergeRequestId || ''}).call()
        ?.threadList?.find((thread) => thread.communicationEventId === communicationEventId) : null
if (!ec.message.hasError() && !anchor) ec.message.addError(ec.resource.expand('Review thread ${communicationEventId} not found', '', {communicationEventId}))
if (!ec.message.hasError()) ec.service.sync().name('mantle.work.GitServices.resolve#ReviewThread').parameters({communicationEventId: communicationEventId,
    resolved: String(resolved) !== 'false'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {resolved: String(resolved) !== 'false'})

const out = ec.service.sync().name('ironstone.projects.CodeServices.submit#Review').parameters({mergeRequestId: mergeRequestId || '', decision: decision || '',
    note: note || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success', message: out.message}]})
